```typescript
import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

interface NodeConfig {
  visual?: { colors?: Record<string, string>; typography?: Record<string, any> };
  cinematicPrimitives?: any[];
}

interface NodeContext {
  fontAtlas: any;
  primitives: Record<string, Function>;
}

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();

  const cardWidth = 2.4;
  const cardHeight = 3.2;
  const padding = 0.5;
  const headerHeight = 0.08;
  const ctaWidth = 1.4;
  const ctaHeight = 0.36;

  const colors = config.visual?.colors || {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // Main card plane
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colors.surface),
  });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0;
  group.add(cardMesh);

  // Header strip (machined metal)
  const headerGeo = new THREE.PlaneGeometry(cardWidth, headerHeight);
  const headerMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors.surface),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });
  const headerMesh = new THREE.Mesh(headerGeo, headerMat);
  headerMesh.position.y = cardHeight / 2 - headerHeight / 2;
  headerMesh.position.z = 0.001;
  group.add(headerMesh);

  // Text layout calculations
  const textBaseY = cardHeight / 2 - padding;
  const textSpecs = [
    { content: 'ATELIER RESERVE', style: 'tier-name', y: textBaseY - 0.2, isFeature: false },
    { content: '$480', style: 'price', y: textBaseY - 0.65, isFeature: false },
    { content: 'PER MONTH, BILLED ANNUALLY', style: 'caption', y: textBaseY - 1.0, isFeature: false },
    { content: 'Quarterly movement service', style: 'feature', y: textBaseY - 1.5, isFeature: true, idx: 0 },
    { content: 'Priority commission slots', style: 'feature', y: textBaseY - 1.85, isFeature: true, idx: 1 },
    { content: 'Private fitting lounge access', style: 'feature', y: textBaseY - 2.2, isFeature: true, idx: 2 },
    { content: 'Lifetime case refinishing', style: 'feature', y: textBaseY - 2.55, isFeature: true, idx: 3 },
  ];

  const featureElements = [];

  textSpecs.forEach((spec) => {
    const typo = config.visual?.typography?.[spec.style] || {};
    const textMesh = ctx.fontAtlas.renderText(spec.content, {
      fontSize: typo.fontSize || 13,
      fontWeight: typo.fontWeight || 400,
      color: new THREE.Color(colors.paper),
    });

    textMesh.position.x = -cardWidth / 2 + padding;
    textMesh.position.y = spec.y;
    textMesh.position.z = 0.002;

    if (spec.isFeature) {
      textMesh.position.y += 0.2;
      if (textMesh.material) {
        textMesh.material.transparent = true;
        textMesh.material.opacity = 0;
      }
      featureElements.push({ mesh: textMesh, targetY: spec.y, index: spec.idx });
    }

    group.add(textMesh);
  });

  // CTA button plane
  const ctaGeo = new THREE.PlaneGeometry(ctaWidth, ctaHeight);
  const ctaMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.5,
  });
  const ctaMesh = new THREE.Mesh(ctaGeo, ctaMat);
  ctaMesh.position.y = -cardHeight / 2 + 0.5 + ctaHeight / 2;
  ctaMesh.position.z = 0.002;
  group.add(ctaMesh);

  // CTA label text
  const ctaLabel = ctx.fontAtlas.renderText('JOIN THE RESERVE', {
    fontSize: 13,
    fontWeight: 700,
    color: new THREE.Color(colors.ink),
  });
  ctaLabel.position.y = ctaMesh.position.y;
  ctaLabel.position.z = 0.003;
  group.add(ctaLabel);

  // Initialize scale for weighted-settle animation
  group.scale.set(1.04, 1.04, 1);

  // Mount animation: weighted-settle
  const scaleTimeline = gsap.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });

  // Feature rows: stagger fade-up
  const featureTimelines = [];
  featureElements.forEach(({ mesh, targetY, index }) => {
    featureTimelines.push(
      gsap.to(mesh.position, {
        y: targetY,
        duration: 0.5,
        delay: index * 0.08,
        ease: 'power2.out',
      })
    );

    if (mesh.material) {
      featureTimelines.push(
        gsap.to(mesh.material, {
          opacity: 1,
          duration: 0.5,
          delay: index * 0.08,
          ease: 'power2.out',
        })
      );
    }
  });

  // CTA press-down on click
  const handleCtaClick = () => {
    gsap.to(ctaMesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(ctaMesh.scale, { x: 1.0, y: 1.0, duration: 0.12, ease: 'back.out' });
      },
    });
  };

  group.userData.handlers = { onClick: handleCtaClick };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf([group.scale, ctaMesh.scale]);
    featureTimelines.forEach(t => t.kill());
    scaleTimeline.kill();
    cardGeo.dispose();
    headerGeo.dispose();
    ctaGeo.dispose();
    cardMat.dispose();
    headerMat.dispose();
    ctaMat.dispose();
  };

  return group;
}
